def semver_sort(versions):
    def parse_key(v):
        # strip build metadata
        core_pre = v.split('+', 1)[0]
        if '-' in core_pre:
            core, pre = core_pre.split('-', 1)
            has_pre = 0  # 0 means has prerelease -> sorts first
        else:
            core = core_pre
            pre = None
            has_pre = 1  # 1 means no prerelease -> sorts later

        major, minor, patch = (int(x) for x in core.split('.'))

        if pre is None:
            pre_key = ()
        else:
            idents = pre.split('.')
            pre_key = []
            for ident in idents:
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))
            pre_key = tuple(pre_key)

        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=parse_key)

